H.background();
const v0 = P.v0, a = P.a;
const Tmax = 6;
const tt = t % Tmax;
const w = H.W, h = H.H;
const xMaxVal = Math.max(2, Math.abs(v0) * Tmax + 0.5 * Math.abs(a) * Tmax * Tmax);
const vp = H.plot2d({ xMin: 0, xMax: Tmax, yMin: -xMaxVal, yMax: xMaxVal, box: { x: 60, y: 50, w: w - 100, h: h * 0.36 } });
vp.grid(); vp.axes();
vp.fn(s => v0 * s + 0.5 * a * s * s, { color: H.colors.accent, width: 3 });
const xNow = v0 * tt + 0.5 * a * tt * tt;
vp.dot(tt, xNow, { r: 6, fill: H.colors.warn });
vp.text("x(t)  [m]", 4, xMaxVal * 0.82, { color: H.colors.accent, size: 13 });
const vMaxVal = Math.max(2, Math.abs(v0) + Math.abs(a) * Tmax);
const vv = H.plot2d({ xMin: 0, xMax: Tmax, yMin: -vMaxVal, yMax: vMaxVal, box: { x: 60, y: h * 0.55, w: w - 100, h: h * 0.36 } });
vv.grid(); vv.axes();
vv.fn(s => v0 + a * s, { color: H.colors.good, width: 3 });
const vNow = v0 + a * tt;
vv.dot(tt, vNow, { r: 6, fill: H.colors.warn });
vv.text("v(t)  [m/s]", 4, vMaxVal * 0.82, { color: H.colors.good, size: 13 });
H.text("Position-time and velocity-time graphs", 24, 24, { color: H.colors.ink, size: 17, weight: 700 });
H.text("t = " + tt.toFixed(2) + " s   x = " + xNow.toFixed(2) + " m   v = " + vNow.toFixed(2) + " m/s   (slope of x-t = v;  slope of v-t = a = " + a.toFixed(1) + ")", 24, h - 14, { color: H.colors.sub, size: 13 });
